CREATE TRIGGER nook_import_objects_inventory_update AFTER UPDATE ON nook_import_objects BEGIN DELETE FROM nook_object_inventory WHERE object_key=OLD.object_key AND NOT EXISTS(SELECT 1 FROM nook_attachments WHERE object_key=OLD.object_key) AND NOT EXISTS(SELECT 1 FROM nook_import_uploads WHERE object_key=OLD.object_key AND state='ready') AND NOT EXISTS(SELECT 1 FROM nook_import_objects WHERE object_key=OLD.object_key AND state='ready'); INSERT OR IGNORE INTO nook_object_inventory SELECT NEW.object_key WHERE NEW.state='ready'; END;
CREATE TRIGGER nook_import_objects_inventory_delete AFTER DELETE ON nook_import_objects BEGIN DELETE FROM nook_object_inventory WHERE object_key=OLD.object_key AND NOT EXISTS(SELECT 1 FROM nook_attachments WHERE object_key=OLD.object_key) AND NOT EXISTS(SELECT 1 FROM nook_import_uploads WHERE object_key=OLD.object_key AND state='ready') AND NOT EXISTS(SELECT 1 FROM nook_import_objects WHERE object_key=OLD.object_key AND state='ready'); END;

-- Guarded reversal removes an unchanged import destination as one transaction.
-- Its membership removal is cleanup, and must not synthesize a live revocation.
DROP TRIGGER nook_creator_revoked;
CREATE TRIGGER nook_creator_revoked AFTER DELETE ON nook_members
WHEN EXISTS(SELECT 1 FROM nook_conversations WHERE id=OLD.conversation AND owner=OLD.user)
 AND NOT EXISTS(SELECT 1 FROM nook_guard g JOIN nook_import_channels ch ON ch.conversation=OLD.conversation WHERE g.id='undo:'||OLD.conversation AND g.ok=1)
BEGIN
 UPDATE nook_conversations SET seq=seq+1 WHERE id=OLD.conversation;
 INSERT INTO nook_events SELECT id,seq,'access-revoked',OLD.user,OLD.user FROM nook_conversations WHERE id=OLD.conversation;
 INSERT INTO nook_creator_revocations SELECT c.id,OLD.user,a.generation,c.seq FROM nook_conversations c JOIN nook_access a ON a.user=OLD.user WHERE c.id=OLD.conversation ON CONFLICT(conversation) DO UPDATE SET user=excluded.user,generation=excluded.generation,event_seq=excluded.event_seq;
END;

-- Local dev identity for an existing store: Base's operator-auth schema/dev-sessions.sql (at the pinned
-- Base commit) with one Nook addition. Base's file assumes nothing names oa_sessions, but four Nook
-- triggers (0011) read it, and SQLite cannot rename over a trigger body that names a missing table.
-- Those triggers are dropped around the rebuild and recreated unchanged below.
-- SQLite cannot change a CHECK in place, so oa_sessions is rebuilt with 'dev' admitted, keeping every
-- row, column, index and constraint. No table has a foreign key to oa_sessions.
DROP TRIGGER IF EXISTS nook_plan_validate;
DROP TRIGGER IF EXISTS nook_invite_accept;
DROP TRIGGER IF EXISTS nook_invite_grant;
DROP TRIGGER IF EXISTS nook_deactivate;
CREATE TABLE oa_sessions_dev_rebuild (
 id TEXT PRIMARY KEY, token_hash TEXT NOT NULL UNIQUE,
 operator_id TEXT NOT NULL REFERENCES oa_operators(id), operator_version INTEGER NOT NULL,
 kind TEXT NOT NULL CHECK(kind IN ('native','review','oidc','password','dev')),
 source_token_id TEXT UNIQUE REFERENCES oa_tokens(id),
 created_at INTEGER NOT NULL, expires_at INTEGER NOT NULL, revoked_at INTEGER
);
INSERT INTO oa_sessions_dev_rebuild(id,token_hash,operator_id,operator_version,kind,source_token_id,created_at,expires_at,revoked_at)
 SELECT id,token_hash,operator_id,operator_version,kind,source_token_id,created_at,expires_at,revoked_at FROM oa_sessions;
DROP TABLE oa_sessions;
ALTER TABLE oa_sessions_dev_rebuild RENAME TO oa_sessions;
CREATE INDEX oa_sessions_operator ON oa_sessions(operator_id);
CREATE TABLE IF NOT EXISTS oa_dev_credentials (
 credential TEXT NOT NULL, id TEXT NOT NULL, created_at INTEGER NOT NULL,
 PRIMARY KEY(credential, id)
);
CREATE TRIGGER nook_plan_validate BEFORE INSERT ON nook_invite_plans
BEGIN
 SELECT CASE WHEN NEW.email<>lower(trim(NEW.email)) OR NEW.state<>'prepared' OR json_array_length(NEW.scopes)<1 OR json_array_length(NEW.scopes)>50 OR (SELECT count(DISTINCT value) FROM json_each(NEW.scopes))<>json_array_length(NEW.scopes) THEN RAISE(ABORT,'invalid_invitation_scope') END;
 SELECT CASE WHEN NOT EXISTS(SELECT 1 FROM oa_operators o JOIN oa_sessions s ON s.operator_id=o.id JOIN nook_access a ON a.user=o.id WHERE o.id=NEW.issuer AND o.status='active' AND o.version=NEW.issuer_version AND (o.role='owner' OR o.role='admin' AND NEW.role='member') AND a.active=1 AND a.mode='member' AND s.id=NEW.issuer_session AND s.operator_version=o.version AND s.revoked_at IS NULL AND s.expires_at>CAST(unixepoch('subsec')*1000 AS INTEGER)) THEN RAISE(ABORT,'inviter_authority_changed') END;
 SELECT CASE WHEN EXISTS(SELECT 1 FROM json_each(NEW.scopes) j WHERE j.type<>'text' OR NOT EXISTS(SELECT 1 FROM nook_conversations c JOIN nook_members m ON m.conversation=c.id WHERE c.id=j.value AND c.kind<>'dm' AND m.user=NEW.issuer AND (SELECT count(*) FROM nook_members capacity WHERE capacity.conversation=c.id)<50)) THEN RAISE(ABORT,'invalid_invitation_scope') END;
END;
CREATE TRIGGER nook_invite_accept BEFORE UPDATE OF status ON oa_operators WHEN OLD.status='invited' AND NEW.status='active'
BEGIN
 SELECT CASE WHEN EXISTS(SELECT 1 FROM oa_sessions s JOIN oa_tokens t ON t.id=s.source_token_id AND t.kind='invite' AND t.operator_id=s.operator_id JOIN nook_invite_plans p ON p.email=NEW.email AND p.role=NEW.role AND p.issuer=t.issuer_id AND p.issuer_version=t.issuer_version AND p.state='prepared' AND p.prepared_at<=t.created_at WHERE s.operator_id=NEW.id AND s.operator_version=OLD.version+1 AND (NOT EXISTS(SELECT 1 FROM oa_operators i JOIN nook_access a ON a.user=i.id WHERE i.id=p.issuer AND i.status='active' AND i.version=p.issuer_version AND a.active=1 AND a.mode='member' AND (i.role='owner' OR i.role='admin' AND p.role='member')) OR EXISTS(SELECT 1 FROM json_each(p.scopes) j WHERE NOT EXISTS(SELECT 1 FROM nook_conversations c JOIN nook_members m ON m.conversation=c.id WHERE c.id=j.value AND c.kind<>'dm' AND m.user=p.issuer AND (SELECT count(*) FROM nook_members capacity WHERE capacity.conversation=c.id)<50)))) THEN RAISE(ABORT,'invitation_scope_changed') END;
END;
CREATE TRIGGER nook_invite_grant AFTER UPDATE OF status ON oa_operators WHEN OLD.status='invited' AND NEW.status='active'
BEGIN
 INSERT INTO nook_actors VALUES(NEW.id,NEW.display_name,NEW.email,NEW.role,1) ON CONFLICT(id) DO UPDATE SET name=excluded.name,email=excluded.email,role=excluded.role,active=1;
 INSERT INTO nook_access SELECT NEW.id,p.mode,1,p.generation FROM oa_sessions s JOIN oa_tokens t ON t.id=s.source_token_id AND t.kind='invite' AND t.operator_id=s.operator_id JOIN nook_invite_plans p ON p.email=NEW.email AND p.role=NEW.role AND p.issuer=t.issuer_id AND p.issuer_version=t.issuer_version AND p.state='prepared' AND p.prepared_at<=t.created_at WHERE s.operator_id=NEW.id AND s.operator_version=OLD.version+1 ON CONFLICT(user) DO UPDATE SET mode=excluded.mode,active=1,generation=excluded.generation;
 INSERT INTO nook_guest_grants SELECT NEW.id,j.value FROM oa_sessions s JOIN oa_tokens t ON t.id=s.source_token_id AND t.kind='invite' AND t.operator_id=s.operator_id JOIN nook_invite_plans p ON p.email=NEW.email AND p.role=NEW.role AND p.issuer=t.issuer_id AND p.issuer_version=t.issuer_version AND p.state='prepared' AND p.prepared_at<=t.created_at,json_each(p.scopes) j WHERE s.operator_id=NEW.id AND s.operator_version=OLD.version+1 AND p.mode='guest';
 INSERT INTO nook_members SELECT j.value,NEW.id FROM oa_sessions s JOIN oa_tokens t ON t.id=s.source_token_id AND t.kind='invite' AND t.operator_id=s.operator_id JOIN nook_invite_plans p ON p.email=NEW.email AND p.role=NEW.role AND p.issuer=t.issuer_id AND p.issuer_version=t.issuer_version AND p.state='prepared' AND p.prepared_at<=t.created_at,json_each(p.scopes) j WHERE s.operator_id=NEW.id AND s.operator_version=OLD.version+1;
 UPDATE nook_invite_plans SET state='accepted' WHERE id IN (SELECT p.id FROM oa_sessions s JOIN oa_tokens t ON t.id=s.source_token_id AND t.kind='invite' AND t.operator_id=s.operator_id JOIN nook_invite_plans p ON p.email=NEW.email AND p.role=NEW.role AND p.issuer=t.issuer_id AND p.issuer_version=t.issuer_version AND p.state='prepared' AND p.prepared_at<=t.created_at WHERE s.operator_id=NEW.id AND s.operator_version=OLD.version+1);
END;
CREATE TRIGGER nook_deactivate AFTER UPDATE OF status ON oa_operators WHEN NEW.status='inactive' AND OLD.status<>NEW.status
BEGIN
 UPDATE oa_sessions SET revoked_at=COALESCE(revoked_at,CAST(unixepoch('subsec')*1000 AS INTEGER)) WHERE operator_id=NEW.id;
 UPDATE nook_access SET active=0,generation=generation+1 WHERE user=NEW.id;
 UPDATE nook_actors SET active=0 WHERE id=NEW.id;
 DELETE FROM nook_members WHERE user=NEW.id;
 DELETE FROM nook_guest_grants WHERE user=NEW.id;
 UPDATE nook_invite_plans SET state='cancelled' WHERE email=NEW.email AND state='prepared';
END;

-- Separate, content-free history keeps real live-row keys absent from archives.
CREATE TABLE nook_erased_actors(id TEXT PRIMARY KEY);
CREATE TABLE nook_erased_messages(id TEXT PRIMARY KEY,conversation TEXT NOT NULL,author TEXT NOT NULL,parent TEXT,version INTEGER NOT NULL,created TEXT NOT NULL,sequence INTEGER NOT NULL,ordinal INTEGER NOT NULL,author_ordinal INTEGER NOT NULL,intent_digest TEXT NOT NULL);
CREATE INDEX nook_erased_history ON nook_erased_messages(conversation,sequence);
CREATE TABLE nook_erased_attachments(id TEXT PRIMARY KEY,conversation TEXT NOT NULL,author TEXT NOT NULL,message TEXT,created TEXT NOT NULL,position INTEGER,intent_digest TEXT NOT NULL);
CREATE TABLE nook_erased_outcomes(id TEXT PRIMARY KEY,conversation TEXT NOT NULL,kind TEXT NOT NULL,version INTEGER NOT NULL,status TEXT NOT NULL);
CREATE VIEW nook_actor_history AS SELECT id,name,email,role,active,0 AS erased FROM nook_actors UNION ALL SELECT id,'Erased member',NULL,NULL,0,1 FROM nook_erased_actors;
CREATE VIEW nook_message_history AS SELECT *,0 AS erased FROM nook_messages UNION ALL SELECT id,conversation,author,'','',parent,version,1,created,'erased:'||id,'[erased]',sequence,ordinal,author_ordinal,1 FROM nook_erased_messages;
CREATE VIEW nook_attachment_history AS SELECT *,0 AS erased FROM nook_attachments UNION ALL SELECT id,conversation,author,message,'','application/octet-stream',0,NULL,0,'deleted',created,NULL,'erased:'||id,position,1 FROM nook_erased_attachments;
CREATE VIEW nook_outcome_history AS SELECT *,0 AS erased FROM nook_outcomes UNION ALL SELECT id,conversation,NULL,NULL,kind,'',NULL,NULL,version,status,NULL,1 FROM nook_erased_outcomes;
CREATE TABLE nook_erasure_receipts(id TEXT PRIMARY KEY,kind TEXT NOT NULL,state TEXT NOT NULL CHECK(state IN ('pending','complete')),counts TEXT NOT NULL,created INTEGER NOT NULL,completed INTEGER);
-- Work references exist only while the destructive transaction sequence is pending.
-- They are removed before completion and never travel in an archive.
CREATE TABLE nook_erasure_work(operation TEXT PRIMARY KEY,target TEXT NOT NULL,kind TEXT NOT NULL,author TEXT NOT NULL,target_role TEXT,conversation TEXT,own INTEGER NOT NULL,phase TEXT NOT NULL DEFAULT 'data',requested_by TEXT NOT NULL,requested_session TEXT NOT NULL,requested_version INTEGER NOT NULL,UNIQUE(kind,target));
CREATE TABLE nook_erasure_blobs(operation TEXT NOT NULL,object_key TEXT NOT NULL,PRIMARY KEY(operation,object_key));
CREATE TRIGGER nook_erasure_reactivation BEFORE UPDATE OF status ON oa_operators WHEN NEW.status='active' AND EXISTS(SELECT 1 FROM nook_erasure_work WHERE target=OLD.id AND kind='member') BEGIN SELECT RAISE(ABORT,'erasure_in_progress'); END;
-- Attribution can be removed without removing the workspace's domain policy.
ALTER TABLE oa_domain_rules RENAME TO nook_old_domain_rules;
CREATE TABLE oa_domain_rules(domain TEXT PRIMARY KEY,provider_id TEXT NOT NULL,created_by TEXT REFERENCES oa_operators(id),created_at INTEGER NOT NULL);
INSERT INTO oa_domain_rules SELECT * FROM nook_old_domain_rules;
DROP TABLE nook_old_domain_rules;
CREATE TRIGGER nook_erasure_message_freeze BEFORE UPDATE ON nook_messages WHEN EXISTS(SELECT 1 FROM nook_erasure_work WHERE target=OLD.id AND kind='message') BEGIN SELECT RAISE(ABORT,'erasure_in_progress'); END;
CREATE TABLE nook_erased_import_messages(id TEXT PRIMARY KEY,job TEXT NOT NULL,conversation TEXT NOT NULL,parent TEXT,sequence INTEGER NOT NULL,source_timestamp TEXT NOT NULL);
CREATE VIEW nook_import_history AS SELECT *,0 AS erased FROM nook_import_records UNION ALL SELECT id,job,'erased:'||id,conversation,'erased',source_timestamp,'{}','','',parent,sequence,1 FROM nook_erased_import_messages;

-- Preserve installation completion without retaining the completing identity.
ALTER TABLE oa_first_run RENAME TO nook_first_run_before_erasure;
CREATE TABLE oa_first_run(singleton INTEGER PRIMARY KEY CHECK(singleton=1),completed_by TEXT REFERENCES oa_operators(id),completed_at INTEGER NOT NULL);
INSERT INTO oa_first_run SELECT * FROM nook_first_run_before_erasure;
DROP TABLE nook_first_run_before_erasure;

-- Other authors' work retains state without linking erased assignees/actions.
CREATE TABLE nook_erased_assignees(outcome TEXT PRIMARY KEY);
CREATE TABLE nook_erased_outcome_actions(outcome TEXT NOT NULL,version INTEGER NOT NULL,body TEXT NOT NULL,status TEXT NOT NULL,deadline TEXT,PRIMARY KEY(outcome,version));

-- Retry commitments keep no caller-provided intent text.
CREATE UNIQUE INDEX nook_erased_message_intent ON nook_erased_messages(intent_digest);
CREATE UNIQUE INDEX nook_erased_attachment_intent ON nook_erased_attachments(intent_digest);

-- Retained current bodies are explicit content, never sanitized tombstones.
CREATE TABLE nook_retained_message_bodies(id TEXT PRIMARY KEY REFERENCES nook_erased_messages(id),body TEXT NOT NULL,body_lower TEXT NOT NULL);
CREATE TABLE nook_retained_import_bodies(id TEXT PRIMARY KEY REFERENCES nook_erased_import_messages(id),body TEXT NOT NULL,body_lower TEXT NOT NULL);
ALTER TABLE nook_erasure_receipts ADD COLUMN member_bodies TEXT NOT NULL DEFAULT 'erase' CHECK(member_bodies IN ('erase','retain'));
ALTER TABLE nook_erasure_work ADD COLUMN member_bodies TEXT NOT NULL DEFAULT 'erase' CHECK(member_bodies IN ('erase','retain'));
ALTER TABLE nook_erasure_work ADD COLUMN authority_class TEXT NOT NULL DEFAULT 'legacy-accepted';
-- Existing irreversible operations are deliberately recorded, not inferred at resume.
UPDATE nook_erasure_work SET authority_class=CASE WHEN own=1 THEN 'author' WHEN kind='member' THEN 'member-manager' WHEN kind='imported-author' THEN 'import-owner' ELSE 'channel-operator' END;
DROP VIEW nook_message_history;
CREATE VIEW nook_message_history AS SELECT *,0 AS erased,0 AS retained_body FROM nook_messages UNION ALL SELECT e.id,e.conversation,e.author,COALESCE(b.body,''),COALESCE(b.body_lower,''),e.parent,e.version,CASE WHEN b.id IS NULL THEN 1 ELSE 0 END,e.created,'erased:'||e.id,CASE WHEN b.id IS NULL THEN '[erased]' ELSE '{}' END,e.sequence,e.ordinal,e.author_ordinal,1,CASE WHEN b.id IS NULL THEN 0 ELSE 1 END FROM nook_erased_messages e LEFT JOIN nook_retained_message_bodies b ON b.id=e.id;
DROP VIEW nook_import_history;
CREATE VIEW nook_import_history AS SELECT *,0 AS erased,0 AS retained_body FROM nook_import_records UNION ALL SELECT e.id,e.job,'erased:'||e.id,e.conversation,'erased',e.source_timestamp,'{}',COALESCE(b.body,''),COALESCE(b.body_lower,''),e.parent,e.sequence,1,CASE WHEN b.id IS NULL THEN 0 ELSE 1 END FROM nook_erased_import_messages e LEFT JOIN nook_retained_import_bodies b ON b.id=e.id;
-- Pending deletions keep attribution only until their bytes are verified absent.
-- Older queue rows can have irrecoverably unknown ownership; member erasure
-- conservatively waits for those already-authorized deletions as well.
ALTER TABLE nook_object_deletes ADD COLUMN erasure_author TEXT;
-- Import custody owner is not content authorship: pending imported media and
-- whole raw ZIPs conservatively have unknown attribution.
UPDATE nook_object_deletes SET erasure_author=COALESCE(
 (SELECT author FROM nook_attachments WHERE object_key=nook_object_deletes.object_key LIMIT 1),
 (SELECT w.author FROM nook_erasure_blobs b JOIN nook_erasure_work w ON w.operation=b.operation WHERE b.object_key=nook_object_deletes.object_key AND w.kind IN ('message','attachment') LIMIT 1))
 WHERE NOT EXISTS(SELECT 1 FROM nook_import_uploads WHERE object_key=nook_object_deletes.object_key)
 AND NOT EXISTS(SELECT 1 FROM nook_import_objects WHERE object_key=nook_object_deletes.object_key);
CREATE TRIGGER nook_delete_attribution AFTER INSERT ON nook_object_deletes WHEN NEW.erasure_author IS NULL BEGIN
 UPDATE nook_object_deletes SET erasure_author=(SELECT author FROM nook_attachments WHERE object_key=NEW.object_key LIMIT 1)
 WHERE object_key=NEW.object_key
 AND NOT EXISTS(SELECT 1 FROM nook_import_uploads WHERE object_key=NEW.object_key)
 AND NOT EXISTS(SELECT 1 FROM nook_import_objects WHERE object_key=NEW.object_key)
 AND NOT EXISTS(SELECT 1 FROM nook_attachments a JOIN nook_import_records r ON r.id=a.message WHERE a.object_key=NEW.object_key);
END;

